const solicitudes = [
  { id: "DEV-1115", monto: 19990, ruta: "APROBACION" },
  { id: "DEV-1116", monto: 69980, ruta: "APROBACION" },
  { id: "DEV-1117", monto: 24990, ruta: "REVISION" },
  { id: "DEV-1118", monto: 79990, ruta: "REVISION" },
  { id: "DEV-1119", monto: 45990, ruta: "RECHAZO" },
  { id: "DEV-1120", monto: 89990, ruta: "REVISION" },
  { id: "DEV-1121", monto: 289990, ruta: "REVISION" },
  { id: "DEV-1122", monto: 45990, ruta: "APROBACION" },
  { id: "DEV-1123", monto: 39980, ruta: "RECHAZO" },
  { id: "DEV-1124", monto: 49980, ruta: "APROBACION" },
  { id: "DEV-1125", monto: 34990, ruta: "RECHAZO" },
  { id: "DEV-1126", monto: 79990, ruta: "REVISION" },
  { id: "DEV-C01", monto: 9990, ruta: "APROBACION" },
  { id: "DEV-C02", monto: 289990, ruta: "REVISION" },
  { id: "DEV-C03", monto: 79990, ruta: "RECHAZO" }
];

let ap = 0, rev = 0, rech = 0, totalMonto = 0;

solicitudes.forEach(item => {
  totalMonto += item.monto;
  if (item.ruta === "APROBACION") ap++;
  else if (item.ruta === "REVISION") rev++;
  else if (item.ruta === "RECHAZO") rech++;
});

const total = solicitudes.length;
const tasaAprobacion = ((ap / total) * 100).toFixed(2) + "%";

return [{
  json: {
    fecha_reporte: new Date().toISOString().split('T')[0],
    total_solicitudes: total,
    monto_total_procesado_clp: totalMonto,
    conteo_aprobaciones: ap,
    conteo_revisiones: rev,
    conteo_rechazos: rech,
    tasa_aprobacion_directa: tasaAprobacion
  }
}];
